export function humanizeIri(iri: string) {
  let local =
    iri
      .replace(/[/#]+$/, "")
      .split(/[/#:]/)
      .at(-1) || iri;
  try {
    local = decodeURIComponent(local);
  } catch {}
  // camelCase local names are property-like ("birthDate" reads "birth date"); PascalCase names and acronyms keep
  // their capitals ("NewYork", "homePageURL").
  const words = /^[a-z]/.test(local)
    ? local.replace(/([a-z\d])([A-Z])(?=[a-z])/g, (_, before: string, capital: string) => `${before} ${capital.toLowerCase()}`)
    : local;
  return (
    words
      .replace(/([a-z\d])([A-Z])/g, "$1 $2")
      .replace(/[_-]+/g, " ")
      .trim() || iri
  );
}
