export function entitySearchQuery(
  search: string,
  properties: string[],
  scope: GraphScope,
  fence = false,
) {
  const literal = JSON.stringify(search).replace(
    /[\u007f-\u009f]/g,
    (c) => "\\u" + c.charCodeAt(0).toString(16).padStart(4, "0"),
  );
  // Labels that contain the term, case-insensitively: an exact label first, then one that starts with it.
  return `SELECT ?source ?predicate ?target WHERE {
 { SELECT ?source (MIN(?rank) AS ?best) WHERE {
 VALUES ?labelProperty { ${[...new Set([...LABEL_PROPERTIES, ...properties])].slice(0, 96).map(iriToken).join(" ")} }
 ${scoped("?source ?labelProperty ?label .", scope)}
 FILTER(isIRI(?source) && isLiteral(?label))
 BIND(LCASE(STR(?label)) AS ?text)
 FILTER(CONTAINS(?text, LCASE(${literal})))
 BIND(IF(?text = LCASE(${literal}), 0, IF(STRSTARTS(?text, LCASE(${literal})), 1, 2)) AS ?rank)
 } GROUP BY ?source ORDER BY ?best LIMIT 20 }
 ${fence ? "BIND(?source AS ?__matchedSource)" : ""}
 ${scoped("?source ?predicate ?target .", scope)}
} LIMIT 100`;
}

export function seedQuery(ids: string[], scope: GraphScope, fence = false) {
  return `SELECT DISTINCT ?source ?predicate ?target WHERE { ${anchors(ids, "source", fence)} ${scoped("?source ?predicate ?target .", scope)} } LIMIT 100`;
}
